import{_ as r,o as s,c as t,ag as a}from"./chunks/framework.DKalukzk.js";const o="/cours/assets/exercice2.CGfctLW4.png",n="/cours/assets/exercice2-1.Bp1-pY8v.png",g=JSON.parse('{"title":"Mise en page et repères du document","description":"Gérer les pages, la table des matières et les en-têtes de façon cohérente","frontmatter":{"title":"Mise en page et repères du document","description":"Gérer les pages, la table des matières et les en-têtes de façon cohérente"},"headers":[],"relativePath":"modules/03-word/02-mise-en-page.md","filePath":"modules/03-word/02-mise-en-page.md"}'),i={name:"modules/03-word/02-mise-en-page.md"};function u(d,e,p,l,c,f){return s(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="mise-en-page-et-reperes-du-document" tabindex="-1">Mise en page et repères du document <a class="header-anchor" href="#mise-en-page-et-reperes-du-document" aria-label="Permalink to &quot;Mise en page et repères du document&quot;">​</a></h1><h2 id="exercice-associe" tabindex="-1">Exercice associé <a class="header-anchor" href="#exercice-associe" aria-label="Permalink to &quot;Exercice associé&quot;">​</a></h2><p>Reprenez le document commencé à l&#39;étape précédente et transformez-le en document plus structuré et plus professionnel.</p><p>À faire dans cette étape :</p><ul><li>créer une page de présentation simple au début du document (avant le premier titre); <ul><li>Elle doit inclure une bordure appliquée uniquement à la première page</li><li>Écrire 3 lignes de texte et les centrer horizontalement (ex.: votre nom, le cours et l&#39;année).</li></ul></li><li>insérer ensuite un <strong>saut de section</strong> pour ajouter une page blanche;</li><li>ajouter une page réservée à la table des matières; <ul><li>Insérer la table des matières sur sa propre page;</li></ul></li><li>ajouter un autre <strong>saut de section</strong> entre la table des matières et le contenu;</li><li>ajuster les marges de la page de table des matières pour qu&#39;elles soient larges;</li><li>configurer un en-tête et un pied de page sur les pages de contenu seulement; <ul><li>l&#39;entête doit apparaître à gauche (votre nom) sur les pages impaires et à droite (Exercice) sur les pages paires;</li></ul></li><li>insérer des numéros de page; <ul><li>Ils doivent apparaître à gauche pour les pages impaires et à droite pour les pages paires;</li></ul></li></ul><figure><img src="'+o+'" alt="Exemple de page de présentation" class="img-bordered"><figcaption>Exemple de page de présentation</figcaption></figure><figure><img src="'+n+'" alt="Exemple de pagination et d&#39;en-têtes et pieds de page" class="img-bordered"><figcaption>Exemple de pagination et d&#39;en-têtes/pieds de page</figcaption></figure><h2 id="ressources-pour-vous-aider" tabindex="-1">Ressources pour vous aider <a class="header-anchor" href="#ressources-pour-vous-aider" aria-label="Permalink to &quot;Ressources pour vous aider&quot;">​</a></h2><h3 id="creer-des-sections-differentes-dans-un-document" tabindex="-1">Créer des sections différentes dans un document <a class="header-anchor" href="#creer-des-sections-differentes-dans-un-document" aria-label="Permalink to &quot;Créer des sections différentes dans un document&quot;">​</a></h3><p>Permet de créer de vraies séparations entre les pages. C&#39;est important pour éviter les documents instables construits avec des Entrées répétées. De plus, cela facilite la mise en page distincte entre une page de présentation, une table des matières, et le reste du contenu.</p><p>Lien très pratique : <a href="https://www.unilim.fr/scd/formation/word-creer-des-sections-differentes-dans-un-document/" target="_blank" rel="noreferrer">Université de Limoges</a></p><p>Lien : <a href="https://support.microsoft.com/fr-fr/office/ins%C3%A9rer-un-saut-de-section-eef20fd8-e38c-4ba6-a027-e503bdf8375c" target="_blank" rel="noreferrer">Microsoft Support</a></p><h3 id="ajouter-une-bordure-a-une-page" tabindex="-1">Ajouter une bordure à une page <a class="header-anchor" href="#ajouter-une-bordure-a-une-page" aria-label="Permalink to &quot;Ajouter une bordure à une page&quot;">​</a></h3><p>Permet d&#39;ajouter une bordure visuelle autour d&#39;une page. C&#39;est utile pour une page de présentation.</p><p>Lien : <a href="https://support.microsoft.com/fr-fr/office/ajouter-une-bordure-%C3%A0-une-page-82c2078a-af86-4f5a-ae2a-517164ba5801?ns=winword&amp;version=90&amp;ui=fr-fr&amp;rs=fr-fr&amp;ad=fr" target="_blank" rel="noreferrer">Microsoft Support</a></p><h3 id="modifier-les-marges-dans-votre-document-word" tabindex="-1">Modifier les marges dans votre document Word <a class="header-anchor" href="#modifier-les-marges-dans-votre-document-word" aria-label="Permalink to &quot;Modifier les marges dans votre document Word&quot;">​</a></h3><p>Explique comment ajuster l&#39;espace en bordure de page. C&#39;est utile notamment pour la page de table des matières, qui doit avoir une présentation différente.</p><p>Lien : <a href="https://support.microsoft.com/fr-fr/office/modifier-les-marges-dans-votre-document-word-c95c1ea1-70b1-4dde-a1da-f5aa2042c829#:~:text=une%20marge%20personnalis%C3%A9e-,S%C3%A9lectionnez%20Disposition%20%3E%20Marges.,OK%20lorsque%20vous%20avez%20termin%C3%A9." target="_blank" rel="noreferrer">Microsoft Support</a></p><h3 id="inserer-un-en-tete-ou-un-pied-de-page" tabindex="-1">Insérer un en-tête ou un pied de page <a class="header-anchor" href="#inserer-un-en-tete-ou-un-pied-de-page" aria-label="Permalink to &quot;Insérer un en-tête ou un pied de page&quot;">​</a></h3><p>Explique comment configurer les zones répétées en haut et en bas du document.</p><p>Lien : <a href="https://support.microsoft.com/fr-fr/office/ins%C3%A9rer-un-en-t%C3%AAte-ou-un-pied-de-page-d832a10c-ef2e-4cff-988a-02bd582db12f" target="_blank" rel="noreferrer">Microsoft Support</a></p><h3 id="inserer-ou-supprimer-des-numeros-de-page" tabindex="-1">Insérer ou supprimer des numéros de page <a class="header-anchor" href="#inserer-ou-supprimer-des-numeros-de-page" aria-label="Permalink to &quot;Insérer ou supprimer des numéros de page&quot;">​</a></h3><p>Permet d&#39;ajouter une pagination.</p><p>Lien : <a href="https://support.microsoft.com/fr-fr/office/ins%C3%A9rer-ou-supprimer-des-num%C3%A9ros-de-page-f50e232f-5873-47a3-9d29-61bea3949c11" target="_blank" rel="noreferrer">Microsoft Support</a></p><h3 id="creer-differents-en-tetes-ou-pieds-de-page-pour-les-pages-paires-et-impaires" tabindex="-1">Créer différents en-têtes ou pieds de page pour les pages paires et impaires <a class="header-anchor" href="#creer-differents-en-tetes-ou-pieds-de-page-pour-les-pages-paires-et-impaires" aria-label="Permalink to &quot;Créer différents en-têtes ou pieds de page pour les pages paires et impaires&quot;">​</a></h3><p>Montre comment varier l&#39;information selon la parité des pages. C&#39;est essentiel pour reproduire fidèlement le modèle demandé. Portez également attention au <strong>bouton suivant</strong>: <code>Lier au précédent</code> si vous commencez une nouvelle section</p><p>Lien : <a href="https://support.microsoft.com/fr-fr/office/cr%C3%A9er-diff%C3%A9rents-en-t%C3%AAtes-ou-pieds-de-page-pour-les-pages-paires-et-impaires-c1b99d1a-38b1-40ff-8338-4897b89be2ef#:~:text=S%C3%A9lectionnez%20Insertion%20%3E%20En%2Dt%C3%AAte%20et,appara%C3%AEtre%20sur%20les%20pages%20paires." target="_blank" rel="noreferrer">Microsoft Support</a></p><h3 id="ajouter-des-numeros-de-page-ou-des-formats-de-numeros-differents-sur-differentes-sections" tabindex="-1">Ajouter des numéros de page ou des formats de numéros différents sur différentes sections <a class="header-anchor" href="#ajouter-des-numeros-de-page-ou-des-formats-de-numeros-differents-sur-differentes-sections" aria-label="Permalink to &quot;Ajouter des numéros de page ou des formats de numéros différents sur différentes sections&quot;">​</a></h3><p>Permet de combiner plusieurs systèmes de pagination dans un même document. C&#39;est utile pour passer des chiffres romains aux chiffres arabes au bon endroit.</p><p>Lien : <a href="https://support.microsoft.com/fr-fr/office/ajouter-des-num%C3%A9ros-de-page-ou-des-formats-de-num%C3%A9ros-diff%C3%A9rents-sur-diff%C3%A9rentes-sections-bb4da2bd-1597-4b0c-9e91-620615ed8c05" target="_blank" rel="noreferrer">Microsoft Support</a></p><h3 id="inserer-une-table-des-matieres" tabindex="-1">Insérer une table des matières <a class="header-anchor" href="#inserer-une-table-des-matieres" aria-label="Permalink to &quot;Insérer une table des matières&quot;">​</a></h3><p>Montre comment générer et mettre à jour automatiquement la table des matières. À faire une fois les titres correctement appliqués dans l&#39;exercice précédent.</p><p>Lien : <a href="https://support.microsoft.com/fr-fr/office/ins%C3%A9rer-une-table-des-mati%C3%A8res-882e8564-0edb-435e-84b5-1d8552ccf0c0" target="_blank" rel="noreferrer">Microsoft Support</a></p>',33)])])}const h=r(i,[["render",u]]);export{g as __pageData,h as default};
